    padding: 4px;
    border-bottom-width: 1px;
  }
  .ew-tabs[data-variant="pills"] [role="tablist"],
  ew-tabs[data-variant="pills"] [role="tablist"] {
    border-bottom: 0;
    gap: 6px;
