  .ew-tabs:not([data-orientation]) { --ew-spec-variant-orientation: horizontal; }
  .ew-tabs[data-size="sm"] { --ew-spec-size: sm; }
  .ew-tabs[data-size="md"] { --ew-spec-size: md; }
  .ew-tabs[data-size="lg"] { --ew-spec-size: lg; }
  .ew-tabs:not([data-size]) { --ew-spec-size: md; }
  @media (prefers-reduced-motion: reduce) {
    .ew-tabs, .ew-tabs *, .ew-tabs *::before, .ew-tabs *::after {
      transition: none !important;
      animation: none !important;
    }
  }
